#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/* ------------------------------------------------------------------
   Helper: check that a string consists only of '0' and '1' and is not
   empty.  Returns true if the string is a valid binary number.
   ------------------------------------------------------------------ */
static bool valid_binary(const char *s)
{
    if (s == NULL || *s == '\0')
        return false;
    for (const char *p = s; *p; ++p)
        if (*p != '0' && *p != '1')
            return false;
    return true;
}

/* ------------------------------------------------------------------
   Main – implements the Turing‑machine described above.
   ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    /* ---------- argument validation -------------------------------- */
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *input = argv[1];
    if (!valid_binary(input)) {
        puts("INVALID_INPUT");
        return 0;
    }

    size_t len = strlen(input);
    /* make a mutable copy that will serve as the tape */
    char *tape = malloc(len + 1);
    if (!tape) {
        perror("malloc");
        return 1;
    }
    memcpy(tape, input, len + 1);   /* include terminating NUL */

    /* ---------- Turing‑machine simulation -------------------------- */
    size_t head = 0;          /* index of the current cell (leftmost) */
    unsigned long steps = 0;  /* number of head moves */
    bool overflow = false;    /* becomes true if we run off the right end */

    while (true) {
        if (tape[head] == '1') {
            /* carry – move right */
            ++head;
            ++steps;
            if (head == len) {          /* ran off the tape → overflow */
                overflow = true;
                break;
            }
            continue;
        }

        /* tape[head] is '0' – we can stop the carry */
        tape[head] = '1';
        ++steps;               /* the write itself counts as a step */
        break;
    }

    /* ---------- output ------------------------------------------------ */
    if (overflow) {
        puts("OVERFLOW");
    } else {
        printf("result=%s\n", tape);
    }
    printf(" steps=%lu\n", steps);

    free(tape);
    return 0;
}
